=== FILE: hls/kernel.h ===
#ifndef KERNEL_H
#define KERNEL_H

#include <ap_fixed.h>
#include <ap_int.h>
#include <stdint.h>

// ── fixed-point type aliases ────────────────────────────────────────────────
// acm / eigenvalues  : bits=22, signed=1, fraction=0  → 23 bits total, 23 int bits
typedef ap_fixed<23, 23> t_acm;

// eigenvectors       : bits=22, signed=1, fraction=20 → 23 bits total, 3 int bits
typedef ap_fixed<23, 3>  t_eig;

// max_iter / ite     : bits=16, signed=0, fraction=0  → 16-bit unsigned int
typedef ap_uint<16>      t_iter;

// matrix size
static const int N = 10;

// complex pair helpers (real + imag stored separately)
struct cx_acm { t_acm re, im; };
struct cx_eig { t_eig re, im; };

// ── top-level declaration ────────────────────────────────────────────────────
void kernel_top(
    cx_acm    acm[N][N],   // input  matrix A
    t_iter    max_iter,    // input  iteration cap
    cx_acm    eigenvalues[N],     // output diagonal (same precision as input)
    cx_eig    eigenvectors[N][N], // output V matrix
    t_iter   &ite,                // output iteration count
    uint32_t &clock_cycles        // C-sim cycle-count proxy
);

#endif // KERNEL_H
=== FILE: hls/kernel.cpp ===
#include "kernel.h"
#include <ap_fixed.h>
#include <ap_int.h>

// ── internal wider arithmetic type ──────────────────────────────────────────
// Use a wider fixed-point for intermediate calculations to preserve precision.
typedef ap_fixed<48, 24> t_wide;
typedef ap_fixed<48, 24> t_trig;   // cos/sin values in [-1,+1]

// ── cordic-style integer square root (integer part only) ────────────────────
// Computes floor(sqrt(x)) for non-negative x using binary search.
static ap_uint<24> isqrt(ap_uint<48> x) {
    ap_uint<24> result = 0;
    ap_uint<48> bit = (ap_uint<48>)1 << 46; // start from highest even bit
    ap_uint<48> rem = x;

    ISQRT_LOOP: for (int i = 0; i < 24; i++) {
        #pragma HLS PIPELINE
        ap_uint<48> trial = (ap_uint<48>)(result << 1 | 1) * (ap_uint<48>)(result << 1 | 1);
        // We iterate bit by bit
        (void)trial;
        // simple restoring method
        if (bit <= rem) {
            ap_uint<48> tmp = result | (ap_uint<48>)(bit >> (i*2 > 46 ? 46 : i*2 > 0 ? i*2 : 0));
            (void)tmp;
        }
        if (bit == 0) break;
        bit >>= 2;
    }
    // Cleaner implementation: digit-by-digit
    result = 0;
    rem = x;
    ap_uint<48> b = (ap_uint<48>)1 << 46;
    ISQRT_LOOP2: for (int i = 0; i < 24; i++) {
        #pragma HLS PIPELINE
        while (b > rem) { b >>= 2; if (b == 0) break; }
        if (b == 0) break;
        ap_uint<48> test = result + b;
        if (rem >= test) {
            rem -= test;
            result = (result >> 1) + b;
        } else {
            result >>= 1;
        }
        b >>= 2;
    }
    return result;
}

// ── integer absolute value of a complex number |a+jb| (approximation) ───────
// Returns sqrt(re^2 + im^2) using wider arithmetic.
static t_wide cx_abs(t_acm re, t_acm im) {
    t_wide r = (t_wide)re;
    t_wide i_v = (t_wide)im;
    t_wide r2 = r * r;
    t_wide i2 = i_v * i_v;
    t_wide sum = r2 + i2;
    // Convert to unsigned integer for isqrt
    ap_ufixed<48,24> sum_u = (ap_ufixed<48,24>)(sum > 0 ? sum : (t_wide)0);
    ap_uint<48> sum_int;
    // scale up by fraction bits if needed; here fraction=0 so direct cast
    sum_int = sum_u.range(47,0);
    ap_uint<24> s = isqrt(sum_int);
    t_wide result = (t_wide)s;
    return result;
}

// ── CORDIC for arctan ────────────────────────────────────────────────────────
// Computes atan(y/x) in a fixed-point friendly way.
// Returns result scaled as a fraction of pi (so result in [-1,1] maps to [-pi,pi]).
// We use a table-based CORDIC with 16 iterations.
// Result is in units where 1.0 = pi/2 radians (i.e., result * pi/2 = angle).
// Actually we return the angle directly in "fixed-point radians * 2^20".

// CORDIC atan table: atan(2^-i) in units of 1/2^20 radians
// atan(2^0)  = 0.7854 rad = 824633 * 2^-20  (but we store as integer * 2^-20)
// We store atan(2^-i) * 2^20 as integer constants.
static const ap_int<32> cordic_atan_table[16] = {
    (ap_int<32>)824633,   // atan(2^0)  = 0.785398 rad
    (ap_int<32>)487469,   // atan(2^-1) = 0.463648 rad
    (ap_int<32>)256194,   // atan(2^-2) = 0.244979 rad
    (ap_int<32>)130526,   // atan(2^-3) = 0.124355 rad
    (ap_int<32>)65666,    // atan(2^-4) = 0.062419 rad
    (ap_int<32>)32848,    // atan(2^-5) = 0.031240 rad
    (ap_int<32>)16424,    // atan(2^-6) = 0.015624 rad
    (ap_int<32>)8212,     // atan(2^-7) = 0.007812 rad
    (ap_int<32>)4106,     // atan(2^-8) = 0.003906 rad
    (ap_int<32>)2053,     // atan(2^-9) = 0.001953 rad
    (ap_int<32>)1027,     // atan(2^-10)= 0.000977 rad
    (ap_int<32>)513,      // atan(2^-11)= 0.000488 rad
    (ap_int<32>)257,      // atan(2^-12)= 0.000244 rad
    (ap_int<32>)128,      // atan(2^-13)= 0.000122 rad
    (ap_int<32>)64,       // atan(2^-14)= 0.000061 rad
    (ap_int<32>)32        // atan(2^-15)= 0.000031 rad
};

// CORDIC gain K ≈ 0.6073 → we scale x,y by 1/K ≈ 1.6468 at start,
// but for angle-mode CORDIC, the gain doesn't affect the angle output.
// Returns angle in fixed-point units of 2^-20 radians (i.e., integer * 2^-20 rad).
static ap_int<32> cordic_atan2(ap_int<32> y_in, ap_int<32> x_in) {
    ap_int<32> x = x_in;
    ap_int<32> y = y_in;
    ap_int<32> z = 0;

    // Quadrant adjustment: rotate to right half-plane
    if (x < 0) {
        if (y >= 0) { x = -x; y = -y; z = (ap_int<32>)3294199; }  // +pi * 2^20 / pi ≈ pi*2^20/pi... actually pi*2^20 = 3294199
        else        { x = -x; y = -y; z = -(ap_int<32>)3294199; }
    }

    CORDIC_LOOP: for (int i = 0; i < 16; i++) {
        #pragma HLS UNROLL
        ap_int<32> x_new, y_new, z_new;
        if (y < 0) {
            x_new = x - (y >> i);
            y_new = y + (x >> i);
            z_new = z - cordic_atan_table[i];
        } else {
            x_new = x + (y >> i);
            y_new = y - (x >> i);
            z_new = z + cordic_atan_table[i];
        }
        x = x_new;
        y = y_new;
        z = z_new;
    }
    return z;
}

// CORDIC for cos/sin
// Input: angle in fixed-point units of 2^-20 radians
// Output: cos and sin scaled by 2^20 (i.e., 1.0 → 2^20 = 1048576)
static void cordic_cossin(ap_int<32> angle_fp, ap_int<32> &cos_out, ap_int<32> &sin_out) {
    // CORDIC gain K ≈ 0.6073, so we pre-scale x by 1/K * 2^20 ≈ 1686629
    // Actually standard CORDIC: start with x=K_inv*2^20, y=0
    // K_inv for 16 iterations ≈ 1.6468 → 1.6468 * 2^20 ≈ 1727706
    ap_int<32> x = (ap_int<32>)1727706;
    ap_int<32> y = 0;
    ap_int<32> z = angle_fp;

    // Quadrant adjustment
    if (z > (ap_int<32>)1647099) {       // > pi/2
        z = z - (ap_int<32>)3294199;
        x = -x;
    } else if (z < -(ap_int<32>)1647099) { // < -pi/2
        z = z + (ap_int<32>)3294199;
        x = -x;
    }

    COSSIN_LOOP: for (int i = 0; i < 16; i++) {
        #pragma HLS UNROLL
        ap_int<32> x_new, y_new, z_new;
        if (z < 0) {
            x_new = x + (y >> i);
            y_new = y - (x >> i);
            z_new = z + cordic_atan_table[i];
        } else {
            x_new = x - (y >> i);
            y_new = y + (x >> i);
            z_new = z - cordic_atan_table[i];
        }
        x = x_new;
        y = y_new;
        z = z_new;
    }
    cos_out = x;
    sin_out = y;
}

// ── kernel top ───────────────────────────────────────────────────────────────
void kernel_top(
    cx_acm    acm[N][N],
    t_iter    max_iter,
    cx_acm    eigenvalues[N],
    cx_eig    eigenvectors[N][N],
    t_iter   &ite,
    uint32_t &clock_cycles
) {
    #pragma HLS INTERFACE ap_ctrl_hs port=return
    #pragma HLS INLINE off

    clock_cycles = 0;
    ite = 0;

    // ── working copies (internal wider arrays) ─────────────────────────────
    // A_re, A_im: local copy of input matrix (fraction=0, 23-bit signed)
    t_acm A_re[N][N], A_im[N][N];
    // V_re, V_im: eigenvector accumulator, initialised to identity
    t_eig V_re[N][N], V_im[N][N];

    INIT_A: for (int i = 0; i < N; i++) {
        #pragma HLS PIPELINE
        for (int j = 0; j < N; j++) {
            A_re[i][j] = acm[i][j].re;
            A_im[i][j] = acm[i][j].im;
            V_re[i][j] = (i == j) ? (t_eig)1 : (t_eig)0;
            V_im[i][j] = (t_eig)0;
        }
    }

    // ── Jacobi sweep ─────────────────────────────────────────────────────
    int last_z = 0;

    JACOBI_OUTER: for (int z = 0; z < 32767; z++) {
        if (z >= (int)max_iter) break;
        last_z = z;

        // 1. Find pivot (p,q) with max |A[i,j]| for i<j
        t_wide off_max = (t_wide)0;
        int p = 0, q = 1;

        PIVOT_I: for (int i = 0; i < N; i++) {
            PIVOT_J: for (int j = i + 1; j < N; j++) {
                #pragma HLS PIPELINE
                t_wide mag = cx_abs(A_re[i][j], A_im[i][j]);
                if (mag > off_max) {
                    off_max = mag;
                    p = i;
                    q = j;
                }
                clock_cycles++;
            }
        }

        // 2. Convergence check: off_max < 1e-8
        //    With fraction=0 and integer values, 1e-8 rounds to 0.
        //    We treat convergence as off_max == 0 (integers → exact zero).
        if (off_max == (t_wide)0) {
            ite = (t_iter)z;
            break;
        }

        // 3. Compute rotation parameters
        // a_pp = A[p,p] (real, diagonal should be real after sweeps)
        // a_qq = A[q,q]
        // a_pq = A[p,q]
        t_wide a_pp_re = (t_wide)A_re[p][p];
        t_wide a_qq_re = (t_wide)A_re[q][q];
        t_wide a_pq_re = (t_wide)A_re[p][q];
        t_wide a_pq_im = (t_wide)A_im[p][q];

        // |a_pq|
        t_wide abs_apq = cx_abs(A_re[p][q], A_im[p][q]);

        // theta = 0.5 * arctan(2*|a_pq| / (a_pp - a_qq))
        // We compute in fixed-point integers scaled by 2^0 (fraction=0)
        // numerator: 2 * abs_apq, denominator: a_pp_re - a_qq_re
        // Convert to integer for CORDIC
        ap_int<32> num_fp = (ap_int<32>)(abs_apq * 2);   // 2*|a_pq|
        ap_int<32> den_fp = (ap_int<32>)(a_pp_re - a_qq_re);

        // Scale for CORDIC: shift up by some bits to increase precision
        // CORDIC expects reasonable integer magnitudes
        // Shift both by 8 bits if small
        ap_int<32> num_s = num_fp << 8;
        ap_int<32> den_s = den_fp << 8;

        ap_int<32> two_theta_fp = cordic_atan2(num_s, den_s); // atan2(num,den) in 2^-20 rad units
        ap_int<32> theta_fp = two_theta_fp >> 1;              // theta = half of that

        // phi = -angle(a_pq) = -atan2(im, re)
        ap_int<32> apq_re_s = (ap_int<32>)a_pq_re << 8;
        ap_int<32> apq_im_s = (ap_int<32>)a_pq_im << 8;
        ap_int<32> angle_apq = cordic_atan2(apq_im_s, apq_re_s);
        ap_int<32> phi_fp = -angle_apq;  // phi = -angle(a_pq)

        // cos(theta), sin(theta)
        ap_int<32> cos_th_fp, sin_th_fp;
        cordic_cossin(theta_fp, cos_th_fp, sin_th_fp);

        // cos(phi), sin(phi)  [needed for exp(±j*phi)]
        ap_int<32> cos_phi_fp, sin_phi_fp;
        cordic_cossin(phi_fp, cos_phi_fp, sin_phi_fp);

        // U[p,p] = cos(theta)
        // U[p,q] = sin(theta) * exp(-j*phi) = sin(theta)*(cos(phi) - j*sin(phi))
        // U[q,p] = sin(theta) * exp(+j*phi) = sin(theta)*(cos(phi) + j*sin(phi))
        // U[q,q] = -cos(theta)   [note: original code has -cos for diagonalisation; standard Jacobi uses cos]
        // We convert CORDIC outputs (scaled by 2^20) to t_eig (ap_fixed<23,3>)
        // 2^20 CORDIC output → 1.0 in real world → in ap_fixed<23,3>, 1.0 = 2^20 (fraction=20), so direct match.

        // Store U elements as t_eig (ap_fixed<23,3>)
        // cos_th_fp is integer in units of 2^-20, so cast directly to ap_fixed<23,3>
        t_eig U_pp_re, U_pp_im;
        t_eig U_pq_re, U_pq_im;
        t_eig U_qp_re, U_qp_im;
        t_eig U_qq_re, U_qq_im;

        // cos_th_fp / 2^20 gives the real value; ap_fixed<23,3> has 20 fraction bits
        // so ap_fixed<23,3>.range = integer value / 2^20
        U_pp_re.range(22,0) = cos_th_fp.range(22,0);
        U_pp_im = (t_eig)0;
        U_qq_re.range(22,0) = (-cos_th_fp).range(22,0);
        U_qq_im = (t_eig)0;

        // sin(theta)*cos(phi) and sin(theta)*sin(phi) — multiply and rescale by 2^20
        ap_int<48> spcp = (ap_int<48>)sin_th_fp * (ap_int<48>)cos_phi_fp; // scaled by 2^40
        ap_int<48> spsp = (ap_int<48>)sin_th_fp * (ap_int<48>)sin_phi_fp;
        ap_int<32> Upq_re_fp = (ap_int<32>)(spcp >> 20);  // scale back to 2^20
        ap_int<32> Upq_im_fp = (ap_int<32>)(-(spsp >> 20)); // -sin(phi) part
        ap_int<32> Uqp_re_fp = (ap_int<32>)(spcp >> 20);
        ap_int<32> Uqp_im_fp = (ap_int<32>)(spsp >> 20);   // +sin(phi) part

        U_pq_re.range(22,0) = Upq_re_fp.range(22,0);
        U_pq_im.range(22,0) = Upq_im_fp.range(22,0);
        U_qp_re.range(22,0) = Uqp_re_fp.range(22,0);
        U_qp_im.range(22,0) = Uqp_im_fp.range(22,0);

        // 4. Compute A' = U† A U (only update the affected rows/columns for efficiency)
        // We do full matrix multiply for correctness.
        // Temp: B = U† * A  (conjugate transpose of U times A)
        // U is identity except at rows/cols p,q

        // B = U^H * A: only rows p and q of B differ from A
        // B[p,:] = conj(U[p,p])*A[p,:] + conj(U[q,p])*A[q,:]
        // B[q,:] = conj(U[p,q])*A[p,:] + conj(U[q,q])*A[q,:]
        // Other rows: B[k,:] = A[k,:]

        // Since U[p,p]=cos(th) (real), U[q,q]=-cos(th) (real), conj = self
        // conj(U[q,p]) = conj(sin*exp(j*phi)) = sin*exp(-j*phi) = U[p,q]
        // conj(U[p,q]) = sin*exp(j*phi) = U[q,p]

        t_wide B_re[N][N], B_im[N][N];

        BMAT_INIT: for (int i = 0; i < N; i++) {
            #pragma HLS PIPELINE
            for (int j = 0; j < N; j++) {
                B_re[i][j] = (t_wide)A_re[i][j];
                B_im[i][j] = (t_wide)A_im[i][j];
            }
        }

        BMAT_PQ: for (int j = 0; j < N; j++) {
            #pragma HLS PIPELINE
            // B[p,j] = U[p,p]*A[p,j] + conj(U[q,p])*A[q,j]
            //        = cos*A[p,j] + U[p,q]^* * A[q,j]  ... wait, let's be careful.
            // U†[p,:] = [conj(U[0,p]), conj(U[1,p]), ..., conj(U[n-1,p])]
            // = conj of column p of U
            // Column p of U: U[p,p]=cos, U[q,p]=sin*exp(j*phi), rest=0
            // So U†[p,p]=cos (real), U†[p,q]=conj(sin*exp(j*phi))=sin*exp(-j*phi)
            // B[p,j] = cos*A[p,j] + sin*exp(-j*phi)*A[q,j]
            t_wide cos_w = (t_wide)U_pp_re;
            t_wide upq_re_w = (t_wide)U_pq_re;
            t_wide upq_im_w = (t_wide)U_pq_im;  // this is sin*cos(phi) component

            // U†[p,q] = conj(U[q,p]) = conj(sin*exp(j*phi)) = sin*exp(-j*phi)
            //         = sin*cos(phi) - j*sin*sin(phi) = U_pq_re - j*U_qp_im ... 
            // Actually U_pq = sin*exp(-j*phi) and U_qp = sin*exp(+j*phi)
            // So conj(U[q,p]) = conj(U_qp) = conj(sin*exp(j*phi)) = sin*exp(-j*phi) = U_pq
            // U†[q,p] = conj(U[p,q]) = conj(sin*exp(-j*phi)) = sin*exp(j*phi) = U_qp

            // B[p,j] = cos*A[p,j] + U_pq * A[q,j]  (complex multiply)
            t_wide Aqj_re = (t_wide)A_re[q][j];
            t_wide Aqj_im = (t_wide)A_im[q][j];
            t_wide Apj_re = (t_wide)A_re[p][j];
            t_wide Apj_im = (t_wide)A_im[p][j];

            // U_pq * A[q,j]: (upq_re + j*upq_im)(Aqj_re + j*Aqj_im)
            t_wide prod1_re = (upq_re_w * Aqj_re - upq_im_w * Aqj_im) >> 20;
            t_wide prod1_im = (upq_re_w * Aqj_im + upq_im_w * Aqj_re) >> 20;

            B_re[p][j] = cos_w * Apj_re - (t_wide)0 * Apj_im + prod1_re; // U_pp is real
            B_im[p][j] = cos_w * Apj_im + prod1_im;
            // scale cos (in 2^20 units) back
            B_re[p][j] = (B_re[p][j]) >> 20;  // wait, we need to handle scaling

            // Actually cos_w is already in ap_fixed<23,3>, so multiplication gives ap_fixed<46,6>
            // and the result needs no extra shift. Let me redo with proper types.
            // Since t_wide = ap_fixed<48,24>, multiplication of two t_wides gives ap_fixed<96,48>
            // which gets truncated to ap_fixed<48,24>. The values should be in range.
            // U_pp_re is in ap_fixed<23,3> ≈ [-4,4), holds cos ≈ ±1 → fine.
            // A values are in ap_fixed<23,23> (integers). Product ≈ integer. OK.
            // upq_re_w is ap_fixed<23,3> ≈ ±1.
            // prod1_re = (upq * Aqj) >> 20: but upq is in units of 2^-20 (fixed<23,3>),
            // Aqj is in units of 1 (fixed<23,23>). Product is in units of 2^-20.
            // So >> 20 would give units of 2^-40, which is wrong.
            // The ap_fixed multiplication handles the binary points automatically!
            // No manual shift needed. Let me fix.
            clock_cycles++;
        }

        // Redo B computation correctly using ap_fixed arithmetic (no manual shifts)
        // Reset B
        BMAT_INIT2: for (int i = 0; i < N; i++) {
            #pragma HLS PIPELINE
            for (int j = 0; j < N; j++) {
                B_re[i][j] = (t_wide)A_re[i][j];
                B_im[i][j] = (t_wide)A_im[i][j];
            }
        }

        // B[p,j] = cos*A[p,j] + U†[p,q]*A[q,j]
        //        = U_pp_re*A[p,j] + (U_pq_re - j*U_pq_im)*A[q,j]
        // (note: U†[p,q] = conj(U[q,p]) = conj(U_qp_re + j*U_qp_im) = U_qp_re - j*U_qp_im
        //  but U_qp_re = U_pq_re and U_qp_im = -U_pq_im so conj(U_qp) = U_pq_re + j*U_pq_im = U_pq ... 
        //  Careful:
        //  U[p,q] = sin(th)*exp(-j*phi) = sin*(cos_phi - j*sin_phi) → re=sin*cos_phi, im=-sin*sin_phi
        //  U[q,p] = sin(th)*exp(+j*phi) = sin*(cos_phi + j*sin_phi) → re=sin*cos_phi, im=+sin*sin_phi
        //  U†[p,q] = conj(U[q,p]) = sin*cos_phi - j*sin*sin_phi = U[p,q] ✓  same
        //  U†[q,p] = conj(U[p,q]) = sin*cos_phi + j*sin*sin_phi = U[q,p] ✓  same
        // So B[p,j] = U_pp_re*A[p,j] + U_pq*(A[q,j])
        // B[q,j] = U†[q,p]*A[p,j] + U†[q,q]*A[q,j]
        //        = U_qp*A[p,j] + U_qq_re*A[q,j]  (U_qq is real = -cos)

        BMAT_UPDATE: for (int j = 0; j < N; j++) {
            #pragma HLS PIPELINE
            t_wide Apj_re_w = (t_wide)A_re[p][j];
            t_wide Apj_im_w = (t_wide)A_im[p][j];
            t_wide Aqj_re_w = (t_wide)A_re[q][j];
            t_wide Aqj_im_w = (t_wide)A_im[q][j];

            t_wide cpp = (t_wide)U_pp_re;   // cos(theta)
            t_wide cqq = (t_wide)U_qq_re;   // -cos(theta)
            t_wide pq_re = (t_wide)U_pq_re;
            t_wide pq_im = (t_wide)U_pq_im;
            t_wide qp_re = (t_wide)U_qp_re;
            t_wide qp_im = (t_wide)U_qp_im;

            // B[p,j] = cpp*(Apj) + U_pq*(Aqj)
            t_wide Bp_re = cpp*Apj_re_w + pq_re*Aqj_re_w - pq_im*Aqj_im_w;
            t_wide Bp_im = cpp*Apj_im_w + pq_re*Aqj_im_w + pq_im*Aqj_re_w;

            // B[q,j] = U_qp*(Apj) + cqq*(Aqj)
            t_wide Bq_re = qp_re*Apj_re_w - qp_im*Apj_im_w + cqq*Aqj_re_w;
            t_wide Bq_im = qp_re*Apj_im_w + qp_im*Apj_re_w + cqq*Aqj_im_w;

            B_re[p][j] = Bp_re;
            B_im[p][j] = Bp_im;
            B_re[q][j] = Bq_re;
            B_im[q][j] = Bq_im;
            clock_cycles++;
        }

        // 5. Compute A' = B * U (in-place)
        // A'[i,p] = B[i,p]*U[p,p] + B[i,q]*U[q,p]
        //         = B[i,p]*cos    + B[i,q]*U_qp
        // A'[i,q] = B[i,p]*U[p,q] + B[i,q]*U[q,q]
        //         = B[i,p]*U_pq   + B[i,q]*(-cos)

        t_wide A2_re[N][N], A2_im[N][N];

        AMAT_INIT: for (int i = 0; i < N; i++) {
            #pragma HLS PIPELINE
            for (int j = 0; j < N; j++) {
                A2_re[i][j] = B_re[i][j];
                A2_im[i][j] = B_im[i][j];
            }
        }

        AMAT_UPDATE: for (int i = 0; i < N; i++) {
            #pragma HLS PIPELINE
            t_wide Bip_re_w = B_re[i][p];
            t_wide Bip_im_w = B_im[i][p];
            t_wide Biq_re_w = B_re[i][q];
            t_wide Biq_im_w = B_im[i][q];

            t_wide cpp = (t_wide)U_pp_re;
            t_wide cqq = (t_wide)U_qq_re;
            t_wide pq_re = (t_wide)U_pq_re;
            t_wide pq_im = (t_wide)U_pq_im;
            t_wide qp_re = (t_wide)U_qp_re;
            t_wide qp_im = (t_wide)U_qp_im;

            // A'[i,p] = B[i,p]*cpp + B[i,q]*(conj... wait, U[q,p] not U†)
            // A' = B*U, so A'[i,p] = sum_k B[i,k]*U[k,p]
            // Only k=p and k=q contribute (U is identity elsewhere)
            // U[p,p]=cos, U[q,p]=U_qp
            t_wide Ap_re = cpp*Bip_re_w + qp_re*Biq_re_w - qp_im*Biq_im_w;
            t_wide Ap_im = cpp*Bip_im_w + qp_re*Biq_im_w + qp_im*Biq_re_w;

            // A'[i,q] = B[i,p]*U[p,q] + B[i,q]*U[q,q]
            t_wide Aq_re = pq_re*Bip_re_w - pq_im*Bip_im_w + cqq*Biq_re_w;
            t_wide Aq_im = pq_re*Bip_im_w + pq_im*Bip_re_w + cqq*Biq_im_w;

            A2_re[i][p] = Ap_re;
            A2_im[i][p] = Ap_im;
            A2_re[i][q] = Aq_re;
            A2_im[i][q] = Aq_im;
            clock_cycles++;
        }

        // Zero out pivot off-diagonal explicitly
        A2_re[p][q] = (t_wide)0; A2_im[p][q] = (t_wide)0;
        A2_re[q][p] = (t_wide)0; A2_im[q][p] = (t_wide)0;

        // Copy A2 → A
        ACOPY: for (int i = 0; i < N; i++) {
            #pragma HLS PIPELINE
            for (int j = 0; j < N; j++) {
                A_re[i][j] = (t_acm)A2_re[i][j];
                A_im[i][j] = (t_acm)A2_im[i][j];
            }
        }

        // 6. Update V = V * U
        // V'[:,p] = V[:,p]*U[p,p] + V[:,q]*U[q,p]
        // V'[:,q] = V[:,p]*U[p,q] + V[:,q]*U[q,q]
        t_wide Vt_re[N][N], Vt_im[N][N];

        VMAT_INIT: for (int i = 0; i < N; i++) {
            #pragma HLS PIPELINE
            for (int j = 0; j < N; j++) {
                Vt_re[i][j] = (t_wide)V_re[i][j];
                Vt_im[i][j] = (t_wide)V_im[i][j];
            }
        }

        VMAT_UPDATE: for (int i = 0; i < N; i++) {
            #pragma HLS PIPELINE
            t_wide Vip_re_w = (t_wide)V_re[i][p];
            t_wide Vip_im_w = (t_wide)V_im[i][p];
            t_wide Viq_re_w = (t_wide)V_re[i][q];
            t_wide Viq_im_w = (t_wide)V_im[i][q];

            t_wide cpp = (t_wide)U_pp_re;
            t_wide cqq = (t_wide)U_qq_re;
            t_wide pq_re = (t_wide)U_pq_re;
            t_wide pq_im = (t_wide)U_pq_im;
            t_wide qp_re = (t_wide)U_qp_re;
            t_wide qp_im = (t_wide)U_qp_im;

            // V'[i,p] = V[i,p]*U[p,p] + V[i,q]*U[q,p]
            t_wide Vp_re = cpp*Vip_re_w + qp_re*Viq_re_w - qp_im*Viq_im_w;
            t_wide Vp_im = cpp*Vip_im_w + qp_re*Viq_im_w + qp_im*Viq_re_w;

            // V'[i,q] = V[i,p]*U[p,q] + V[i,q]*U[q,q]
            t_wide Vq_re = pq_re*Vip_re_w - pq_im*Vip_im_w + cqq*Viq_re_w;
            t_wide Vq_im = pq_re*Vip_im_w + pq_im*Vip_re_w + cqq*Viq_im_w;

            Vt_re[i][p] = Vp_re; Vt_im[i][p] = Vp_im;
            Vt_re[i][q] = Vq_re; Vt_im[i][q] = Vq_im;
            clock_cycles++;
        }

        VCOPY: for (int i = 0; i < N; i++) {
            #pragma HLS PIPELINE
            for (int j = 0; j < N; j++) {
                V_re[i][j] = (t_eig)Vt_re[i][j];
                V_im[i][j] = (t_eig)Vt_im[i][j];
            }
        }

        ite = (t_iter)(z + 1);
    }

    // ── Write outputs ─────────────────────────────────────────────────────
    OUT_DIAG: for (int i = 0; i < N; i++) {
        #pragma HLS PIPELINE
        eigenvalues[i].re = A_re[i][i];
        eigenvalues[i].im = A_im[i][i];
    }

    OUT_VEC: for (int i = 0; i < N; i++) {
        #pragma HLS PIPELINE
        for (int j = 0; j < N; j++) {
            eigenvectors[i][j].re = V_re[i][j];
            eigenvectors[i][j].im = V_im[i][j];
        }
    }
