    // File contains: for each element, one line "real imag" (interleaved)
    // Shape [10,10] → 100 elements, call index 0 is the first 100 lines.
    {
        snprintf(path, sizeof(path), "%sin_A.txt", IO_DIR);
        FILE *fp = fopen(path, "r");
        if (!fp) { fprintf(stderr, "Cannot open %s\n", path); return 1; }
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                double re_d = 0.0, im_d = 0.0;
                if (fscanf(fp, "%lf %lf", &re_d, &im_d) != 2) {
                    fprintf(stderr, "Read error in_A.txt at [%d][%d]\n", i, j);
                    fclose(fp); return 1;
                }
                // Convert to ap_fixed<23,23> (integer, fraction=0)
                long long re_i = (long long)re_d;
                long long im_i = (long long)im_d;
                acm[i][j].re = (t_acm)re_i;
                acm[i][j].im = (t_acm)im_i;
            }
        }
        fclose(fp);
    }

    // ── Read in_max_iter.txt (call index 0: first scalar) ───────────────
    {
        snprintf(path, sizeof(path), "%sin_max_iter.txt", IO_DIR);
        FILE *fp = fopen(path, "r");
        if (!fp) { fprintf(stderr, "Cannot open %s\n", path); return 1; }
        long long v = 0;
        if (fscanf(fp, "%lld", &v) != 1) {
            fprintf(stderr, "Read error in_max_iter.txt\n");
            fclose(fp); return 1;
        }
        max_iter_val = (t_iter)(unsigned short)v;
        fclose(fp);
    }

